import java.util.*;
// 模板导入，排序只在原数组上交换。
class Solution {
    public void sortColors(int[] nums) {
        int zero = 0;
        // [0, zero) 全部是 0。
        int current = 0;
        // [zero, current) 全部是 1。
        int two = nums.length - 1;
        // (two, n-1] 全部是 2。
        while (current <= two) {
            if (nums[current] == 0) {
                swap(nums, current, zero);
                zero++;
                current++;
                // 换回来的是已处理过的 1，current 可以前进。
            } else if (nums[current] == 2) {
                swap(nums, current, two);
                two--;
                // 右边换入的值还没看过，current 停在原地再判断。
            } else {
                current++;
            }
        }
    }
    private void swap(int[] nums, int i, int j) {
        int temp = nums[i];
        nums[i] = nums[j];
        nums[j] = temp;
    }
}

