import java.util.*;
// Java 常用集合、队列、堆与数组工具
class Solution {
    public ListNode removeNthFromEnd(ListNode head, int n) {
        // 哑节点统一承接原头，删头时不用另写分支。
        ListNode dummy = new ListNode(0, head);
        ListNode fast = dummy;
        ListNode slow = dummy;
        // 只走 fast，使它比 slow 超前 n 个节点。
        for (int i = 0;
        i < n;
        i++) {
            fast = fast.next;
        }
        // fast 停在尾时，slow 正好停在待删节点的前驱。
        while (fast.next != null) {
            fast = fast.next;
            slow = slow.next;
        }
        slow.next = slow.next.next;
        // 绕过 slow 的后继，完成删除。
        return dummy.next;
    }
}

