class Solution {
    public int preimageSizeFZF(int k) {
        // 等于 k 的区间长度 = 第一次达到 k+1 的位置 − 第一次达到 k 的位置
        return (int) (leftBound(k + 1) - leftBound(k));
    }
    private long leftBound(int k) {
        long left = 0, right = 5L * (k + 1);
        while (left < right) {
            long mid = left + ((right - left) >>> 1);
            if (trailingZeroes(mid) >= k) {
                right = mid;
                // 末尾零已经不少于 k，答案在左半边（含 mid）
            } else {
                left = mid + 1;
            }
        }
        return left;
    }
