class Solution {
    public List<String> removeInvalidParentheses(String s) {
        List<String> ans = new ArrayList<>();
        Set<String> visited = new HashSet<>();
        Queue<String> queue = new LinkedList<>();
        queue.offer(s);
        visited.add(s);
        boolean found = false;
        while (!queue.isEmpty()) {
            String cur = queue.poll();
            if (isValid(cur)) {
                // 同一层删除次数相同，收集本层合法串
                ans.add(cur);
                found = true;
            }
            if (found) {
                // 已有最少删除方案，不再继续删
                continue;
            }
            for (int i = 0;
            i < cur.length();
            i++) {
                char c = cur.charAt(i);
                if (c != '(' && c != ')') {
                    continue;
                }
                // 只删一个括号，生成下一层候选
                String next = cur.substring(0, i) + cur.substring(i + 1);
                if (visited.add(next)) {
                    queue.offer(next);
                }
            }
        }
        return ans;
    }
    private boolean isValid(String s) {
        int balance = 0;
        for (char c : s.toCharArray()) {
            if (c == '(') {
                balance++;
            } else if (c == ')') {
                // 右括号更多则不合法
                if (balance == 0) {
                    return false;
                }
                balance--;
            }
        }
        return balance == 0;
    }
}

