class Solution {
    // 只通过该接口取偏置位，保证不引入别的随机源。
    interface BiasedBitSource {
        int nextBit();
        // 独立返回 0 或 1，P(1)=p。
    }
    private final BiasedBitSource source;
    public Solution(BiasedBitSource source) {
        this.source = source;
    }
    // 01 与 10 等概率，用来抽出一个不偏向的 bit。
    private int fairBit() {
        while (true) {
            int first = source.nextBit();
            int second = source.nextBit();
            // P(01)=(1-p)p 与 P(10) 相同，返回 0 不会偏向某一侧。
            if (first == 0 && second == 1) {
                return 0;
            }
            if (first == 1 && second == 0) {
                return 1;
            }
            // 00、11 的概率一般不等，不能当公平位，丢掉重抽。
        }
    }
    public double nextUniformDouble() {
        long bits = 0L;
        // double 可区分的 [0,1) 网格是 2^53 个点，所以凑满 53 位。
        for (int i = 0;
        i < 53;
        i++) {
            bits = (bits << 1) | fairBit();
        }
        // bits 均匀落在 [0, 2^53)，再除以 2^53 就落在 [0,1)。
        return bits / (double) (1L << 53);
    }
}

