class Solution {
    private static final double EPS = 1e-12;
    public double binaryCrossEntropy(int label, double probabilityPositive) {
        if (label != 0 && label != 1) {
            throw new IllegalArgumentException("label 只能为 0 或 1");
        }
        // 夹在开区间内，避免 log(0)。
        double p = Math.max(EPS, Math.min(1.0 - EPS, probabilityPositive));
        return -(label * Math.log(p) + (1 - label) * Math.log(1.0 - p));
    }
    // 未归一化 logits 上用 log-sum-exp，等价于 -log softmax。
    public double multiClassCrossEntropy(double[] logits, int labelIndex) {
        if (logits == null || logits.length == 0) {
            throw new IllegalArgumentException("logits 不能为空");
        }
        if (labelIndex < 0 || labelIndex >= logits.length) {
            throw new IllegalArgumentException("labelIndex 越界");
        }
        double maxLogit = -Double.MAX_VALUE;
        for (double value : logits) {
            if (!Double.isFinite(value)) {
                throw new IllegalArgumentException("logit 必须是有限数值");
            }
            maxLogit = Math.max(maxLogit, value);
        }
        // 减去 maxLogit 再 exp，避免指数溢出。
        double sumExp = 0.0;
        for (double value : logits) {
            sumExp += Math.exp(value - maxLogit);
