import java.util.concurrent.*;
public class ConcurrentSquareCalculator {
    public long[] squareAll(int[] nums) throws InterruptedException {
        long[] result = new long[nums.length];
        if (nums.length == 0) {
            System.out.println(Arrays.toString(result));
            return result;
        }
        ExecutorService executor = Executors.newFixedThreadPool(
        Math.min(nums.length, Runtime.getRuntime().availableProcessors()));
        CountDownLatch latch = new CountDownLatch(nums.length);
        boolean complete = false;
        try {
            for (int i = 0;
            i < nums.length;
            i++) {
                final int index = i;
                executor.execute(() -> {
                    try {
                        result[index] = (long) nums[index] * nums[index];
                    }
                    finally {
                        latch.countDown();
                    }
                }
                );
            }
            latch.await();
            complete = true;
            System.out.println(Arrays.toString(result));
            return result;
        }
        finally {
            if (complete) executor.shutdown();
            else executor.shutdownNow();
        }
    }
}

