import java.util.*;
import java.util.concurrent.locks.*;
class Solution {
    private final Lock lock = new ReentrantLock();
    private final Condition turnChanged = lock.newCondition();
    private int nextRow = 0;
    public void printRowsAlternately(int[][] matrix) throws InterruptedException {
        Thread evenIndexThread = new Thread(() -> printParity(matrix, 0), "even-index-row");
        Thread oddIndexThread = new Thread(() -> printParity(matrix, 1), "odd-index-row");
        evenIndexThread.start();
        oddIndexThread.start();
        evenIndexThread.join();
        oddIndexThread.join();
    }
    private void printParity(int[][] matrix, int parity) {
        while (true) {
            lock.lock();
            try {
                // 不是自己的奇偶行就等待，避免抢先打印。
                while (nextRow < matrix.length && nextRow % 2 != parity) {
                    turnChanged.await();
                }
                // 唤醒对方，否则它会停在 await 无法结束。
                if (nextRow >= matrix.length) {
                    turnChanged.signalAll();
                    return;
                }
                System.out.println(Arrays.toString(matrix[nextRow]));
                nextRow++;
                // 交出行号后再唤醒，对方才能通过奇偶检查。
                turnChanged.signalAll();
            }
            catch (InterruptedException e) {
                Thread.currentThread().interrupt();
                return;
            }
            finally {
                lock.unlock();
            }
        }
    }
}

