import java.util.*;
import java.util.concurrent.locks.*;
class Solution {
    public void printRowsAlternately(int[][] matrix) throws InterruptedException {
        Objects.requireNonNull(matrix);
        // State belongs to this invocation, so repeated calls start at row zero.
        class Run {
            final Lock lock = new ReentrantLock();
            final Condition changed = lock.newCondition();
            int nextRow;
            boolean cancelled;
            void cancel() {
                lock.lock();
                try {
                    cancelled = true;
                    changed.signalAll();
                }
                finally {
                    lock.unlock();
                }
            }
            void printParity(int parity) {
                lock.lock();
                try {
                    while (!cancelled && nextRow < matrix.length) {
                        while (!cancelled && nextRow < matrix.length && nextRow % 2 != parity)
                        changed.await();
                        if (cancelled || nextRow >= matrix.length) return;
                        System.out.println(Arrays.toString(matrix[nextRow++]));
                        changed.signalAll();
                    }
                }
                catch (InterruptedException e) {
                    cancelled = true;
                    changed.signalAll();
                    Thread.currentThread().interrupt();
                }
                finally {
                    lock.unlock();
                }
            }
        }
        Run run = new Run();
        Thread even = new Thread(() -> run.printParity(0), "even-index-row");
        Thread odd = new Thread(() -> run.printParity(1), "odd-index-row");
        even.start();
        odd.start();
        try {
            even.join();
            odd.join();
        }
        catch (InterruptedException e) {
            run.cancel();
            even.interrupt();
            odd.interrupt();
            throw e;
        }
    }
}

