// 代表题 ML 2。分数升序排列，秩从 1 开始，完全相同的分数取平均秩。
// AUC = (正样本秩和 - nPos*(nPos+1)/2) / (nPos*nNeg)，即随机一正一负里正分更高的概率。
// 换题若分数越小越好，把比较方向反过来，或先取负号再调用。
static double auc(int[] y, double[] score) {
    int n = y.length;
    Integer[] idx = new Integer[n];
    for (int i = 0;
    i < n;
    i++) idx[i] = i;
    Arrays.sort(idx, (a, b) -> Double.compare(score[a], score[b]));
    double[] rank = new double[n];
    for (int i = 0;
    i < n;
    ) {
        int j = i;
        while (j + 1 < n && score[idx[j + 1]] == score[idx[i]]) j++;
        double avg = ((i + 1) + (j + 1)) / 2.0;
        for (int k = i;
        k <= j;
        k++) rank[idx[k]] = avg;
        i = j + 1;
    }
    double sumPos = 0;
    int nPos = 0, nNeg = 0;
    for (int i = 0;
    i < n;
    i++) {
        if (y[i] == 1) {
            sumPos += rank[i];
            nPos++;
        } else nNeg++;
    }
    return (sumPos - nPos * (nPos + 1) / 2.0) / (nPos * nNeg);
}

