    i++) go[i] = new Semaphore(0);
    for (int i = 0;
    i < n;
    i++) {
        final int idx = i;
        ts[i] = new Thread(() -> {
            try {
                go[idx].acquire();
                System.out.println(idx + 1);
                if (idx + 1 < n) go[idx + 1].release();
            }
            catch (InterruptedException e) {
                Thread.currentThread().interrupt();
            }
        }
        );
    }
    for (Thread t : ts) t.start();
    go[0].release();
    for (Thread t : ts) {
        try {
            t.join();
        }
        catch (InterruptedException e) {
            Thread.currentThread().interrupt();
        }
    }
}

